// Every shape that an earlier reader of the text flagged, kept as a corpus so that no later rule loses one.
// `code-loading-regression.test.ts` asserts that each row is still flagged by the reading as it is now, and names the row
// that is not. A row is added when a reader flags a shape; a row is never removed because a rule is rewritten.
export interface Shape {
  readonly group: string;
  readonly text: string;
}

